import pg from 'pg';
import Redis from 'ioredis';
import {brotliDecompressSync} from 'node:zlib';
import {createHash} from 'node:crypto';
import {writeFile,mkdir} from 'node:fs/promises';
void pg;void Redis;
const payload=brotliDecompressSync(Buffer.from('','base64'));
if(payload.length!==1863799||createHash('sha256').update(payload).digest('hex')!=='6230edb637dd4a2d8c5b553132a1c3fc9cbb08b7004fe4f8e61332d10dc3a7ee')throw Error('NATIVE72_PACKAGE_INTEGRITY_MISMATCH');
const files=JSON.parse(payload.toString('utf8'));
await mkdir(new URL('./native72-batch01/',import.meta.url),{recursive:true,mode:0o700});
for(const file of files){
 if(!/^(?:native-slot-runtime\.mjs|native72-batch01\/[a-z0-9-]+\.(?:mjs|json))$/.test(file.path))throw Error('NATIVE72_PACKAGE_PATH_INVALID');
 const bytes=Buffer.from(file.source,'utf8');
 if(bytes.length!==file.bytes||createHash('sha256').update(bytes).digest('hex')!==file.sha256)throw Error('NATIVE72_MODULE_INTEGRITY_MISMATCH');
 await writeFile(new URL('./'+file.path,import.meta.url),bytes,{mode:0o600});
}
await import(new URL('./native-slot-runtime.mjs',import.meta.url).href);
